import { gs, type GlideRecord } from '@servicenow/glide'
import MD5 from 'crypto-js/md5'
import Handlebars from 'handlebars'

export function rule(current: GlideRecord, previous: GlideRecord) {
    gs.info(MD5(current.getValue() + previous.getValue()).toString())
    gs.info(Handlebars.compile('Hello {{name}}')({ name: 'World' }))
}
